"  const handleToggleCategoryActive = async (category) => {
    if (getStaffPermissions()?.pos_access?.OperationManagement?.ItemsManagement?.category_enabled_disabled === false) {
      toast.error("You do not have permission to enable/disable categories.");
      return;
    }
    const nextActive = !category.is_active;
    try {
      if (navigator.onLine) {
        await posService.updateCategory(category.id, { is_active: nextActive });
      } else {
        const unsyncedCats = JSON.parse(localStorage.getItem('pos_unsynced_categories') || '{}');
        unsyncedCats[category.id] = nextActive;
        localStorage.setItem('pos_unsynced_categories', JSON.stringify(unsyncedCats));
      }

      setItemMgmtCategories(prev => {
        const nextCats = prev.map(c => c.id === category.id ? { ...c, is_active: nextActive } : c);
        localStorage.setItem('pos_item_mgmt_categories', JSON.stringify(nextCats));
        return nextCats;
      });

      if (!navigator.onLine) {
        toast.error("Offline Mode: Category toggled locally");
      } else {
        await refreshBillingCatalog();
        try {
           const ogRes = await posService.getOptionGroups();
           setOptionGroups(ogRes.data || []);
        } catch (err) {
           console.error("Failed to refresh option groups:", err);
        }
        toast.success(`Category "${category.name}" status updated`);
      }
    } catch (err) {
      console.error('Failed to update category active state:', err);
      toast.error('Failed to update category status');
    }
  };"
